const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sakhaRepublic = ee.Geometry.Rectangle([105, 55, 160, 75]); // Approximate bounds of Sakha Republic
  const targetDate = '2020-08-06';

  // 2. Data Acquisition - MODIS Active Fires
  const firesCollection = ee.FeatureCollection('MODIS/006/MCD14DL')
    .filterDate(targetDate, ee.Date(targetDate).advance(1, 'day'))
    .filterBounds(sakhaRepublic)
    .filter(ee.Filter.gte('confidence', 30)); // Medium to high confidence fires

  const fireCount = firesCollection.size();
  const countInfo = fireCount.getInfo();

  console.log(`Fire detections on ${targetDate}: ${countInfo}`);

  // Check for empty collection
  if (countInfo === 0) {
    console.log("No fire detections found.");
    console.log("<answer>B</answer>");
    return;
  }

  // Get sample fire locations for validation
  const sampleFires = firesCollection.limit(3);
  const sampleInfo = sampleFires.getInfo();
  console.log(`Sample fire locations: ${sampleInfo.features ? sampleInfo.features.length : 0}`);

  // Final decision
  if (countInfo > 8) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
